(() => {
  "use strict";

  // ==========================================
  // KONFIGURASI BACKEND GOOGLE APPS SCRIPT
  // ==========================================
  const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzETotWT7sOHPvwv4p-C0fBqfwcPjwRCnmsw0Pv7eKFUgXuScvBxHi0hYPa8wSedZuyLw/exec";
  const GAS_API_KEY = "SIMPEL-V2-SECRET-KEY-2026";
  const STORAGE_KEY = "SIMPEL_SESSION_RESUME_V3";

  // State tertutup di dalam IIFE (tidak dapat diakses/diubah dari DevTools Console)
  const state = {
    isActive: false,
    isSubmitting: false,
    isTransitioning: false,
    sessionToken: "",
    token: "",
    npm: "",
    nama: "",
    prefillEmail: "",
    dataKuis: null,
    soalList: [],
    currentIndex: 0,
    userAnswers: [],
    cheatCount: 0,
    lastCheatTimestamp: 0,
    unfocusedSinceMs: 0,
    answeredStreak: 0,
    timerInterval: null,
    remainingSeconds: 0,
    targetEndPerfMs: 0,
    initialViewportArea: window.innerWidth * window.innerHeight,
    initialAspectRatio: window.innerWidth / Math.max(1, window.innerHeight)
  };

  let waitingPollInterval = null;

  const audioPrefs = {
    sfxEnabled: true,
    bgmEnabled: false,
    audioCtx: null,
    synthBgmInterval: null
  };

  function escHtml(str) {
    if (str === null || str === undefined) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  // ==========================================
  // WRAPPER FETCH KE GAS (BEBAS PREFLIGHT OPTIONS + AUTO RETRY + API KEY)
  // ==========================================
  async function callGasApi(payload, maxRetries = 3) {
    let attempt = 0;
    let lastError = null;
    const requestBody = Object.assign({ apiKey: GAS_API_KEY }, payload);

    while (attempt < maxRetries) {
      try {
        const response = await fetch(GAS_WEB_APP_URL, {
          method: "POST",
          redirect: "follow",
          headers: {
            "Content-Type": "text/plain;charset=utf-8"
          },
          body: JSON.stringify(requestBody)
        });

        if (!response.ok) {
          throw new Error("HTTP " + response.status);
        }

        const text = await response.text();
        return JSON.parse(text);
      } catch (err) {
        lastError = err;
        attempt++;
        if (attempt < maxRetries) {
          await new Promise(resolve => setTimeout(resolve, 900 * attempt));
        }
      }
    }
    throw new Error("Gagal terhubung ke server ujian: " + (lastError ? lastError.message : "Timeout"));
  }

  // ==========================================
  // SERVER-SYNCED AUTO-RESUME (TANPA MENYIMPAN SOAL & WAKTU DI LOCALSTORAGE)
  // ==========================================
  function saveMinimalSessionLocal() {
    if (!state.isActive || state.isSubmitting) return;
    const minimalSnapshot = {
      sessionToken: state.sessionToken,
      token: state.token,
      npm: state.npm,
      nama: state.nama,
      currentIndex: state.currentIndex,
      userAnswers: state.userAnswers,
      answeredStreak: state.answeredStreak
    };
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(minimalSnapshot));
    } catch (e) {}
  }

  function clearMinimalSessionLocal() {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {}
  }

  async function restoreServerSyncedSession(urlToken) {
    let saved = null;
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return false;
      saved = JSON.parse(raw);
    } catch (e) {
      clearMinimalSessionLocal();
      return false;
    }

    if (!saved || !saved.sessionToken || !saved.token || !saved.npm) {
      clearMinimalSessionLocal();
      return false;
    }

    if (urlToken && String(saved.token).trim() !== String(urlToken).trim()) {
      return false;
    }

    const btn = document.getElementById("btnMulaiKuis");
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = '<span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span> Memulihkan Sesi Ujian...';
    }

    try {
      const res = await callGasApi({
        action: "mulaiKuis",
        token: saved.token,
        npm: saved.npm,
        nama: saved.nama,
        resumeSessionToken: saved.sessionToken
      }, 2);

      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<i class="bi bi-play-fill text-lg"></i> Masuk & Mulai Kuis';
      }

      if (!res || res.status !== "success") {
        clearMinimalSessionLocal();
        return false;
      }

      launchQuizArena(saved.token, saved.npm, saved.nama, res, {
        currentIndex: saved.currentIndex || 0,
        userAnswers: Array.isArray(saved.userAnswers) ? saved.userAnswers : [],
        answeredStreak: saved.answeredStreak || 0
      });

      Swal.fire({
        toast: true,
        position: "top-end",
        icon: "info",
        title: "Sesi ujian & waktu server dipulihkan",
        showConfirmButton: false,
        timer: 2500
      });
      return true;
    } catch (err) {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<i class="bi bi-play-fill text-lg"></i> Masuk & Mulai Kuis';
      }
      return false;
    }
  }

  // ==========================================
  // ENGINE EFEK SUARA & MUSIK LATAR (WEB AUDIO)
  // ==========================================
  function ensureAudioContext() {
    if (!audioPrefs.audioCtx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) audioPrefs.audioCtx = new AudioCtx();
    }
    if (audioPrefs.audioCtx && audioPrefs.audioCtx.state === "suspended") {
      audioPrefs.audioCtx.resume();
    }
  }

  function playSfx(type) {
    if (!audioPrefs.sfxEnabled) return;
    ensureAudioContext();
    const ctx = audioPrefs.audioCtx;
    if (!ctx) return;

    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    if (type === "warning") {
      osc.type = "square";
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(349.23, now + 0.12);
      gain.gain.setValueAtTime(0.14, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === "finish") {
      osc.type = "triangle";
      [523.25, 659.25, 783.99, 1046.5].forEach((freq, idx) => {
        osc.frequency.setValueAtTime(freq, now + idx * 0.1);
      });
      gain.gain.setValueAtTime(0.2, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
      osc.start(now);
      osc.stop(now + 0.6);
    } else {
      osc.type = "sine";
      osc.frequency.setValueAtTime(620, now);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
      osc.start(now);
      osc.stop(now + 0.12);
    }
  }

  function toggleSfx() {
    audioPrefs.sfxEnabled = !audioPrefs.sfxEnabled;
    const icon = document.getElementById("iconSfx");
    if (icon) {
      icon.className = audioPrefs.sfxEnabled ? "bi bi-volume-up-fill text-base" : "bi bi-volume-mute-fill text-base opacity-50";
    }
  }

  function startBgm() {
    const customUrl = state.dataKuis && state.dataKuis.musikCustom ? String(state.dataKuis.musikCustom).trim() : "";
    const audioEl = document.getElementById("customBgmAudio");

    if (customUrl && audioEl) {
      audioEl.src = customUrl;
      audioEl.volume = 0.35;
      audioEl.play().catch(() => {});
    } else {
      ensureAudioContext();
      stopSynthBgm();
      const notes = [261.63, 329.63, 392.00, 493.88, 392.00, 329.63];
      let step = 0;
      audioPrefs.synthBgmInterval = setInterval(() => {
        if (!audioPrefs.bgmEnabled || !audioPrefs.audioCtx) return;
        const ctx = audioPrefs.audioCtx;
        const now = ctx.currentTime;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = "sine";
        osc.frequency.setValueAtTime(notes[step % notes.length], now);
        gain.gain.setValueAtTime(0.025, now);
        gain.gain.exponentialRampToValueAtTime(0.0005, now + 0.55);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now);
        osc.stop(now + 0.55);
        step++;
      }, 650);
    }
  }

  function stopSynthBgm() {
    if (audioPrefs.synthBgmInterval) {
      clearInterval(audioPrefs.synthBgmInterval);
      audioPrefs.synthBgmInterval = null;
    }
  }

  function stopBgm() {
    const audioEl = document.getElementById("customBgmAudio");
    if (audioEl) audioEl.pause();
    stopSynthBgm();
  }

  function toggleBgm() {
    audioPrefs.bgmEnabled = !audioPrefs.bgmEnabled;
    const icon = document.getElementById("iconBgm");
    if (audioPrefs.bgmEnabled) {
      if (icon) icon.className = "bi bi-music-note-beamed text-base text-blue-500";
      startBgm();
    } else {
      if (icon) icon.className = "bi bi-music-note-beamed text-base opacity-50";
      stopBgm();
    }
  }

  // ==========================================
  // TEMA ANTARMUKA
  // ==========================================
  function applyQuizTheme(themeName) {
    const validThemes = ["Classic", "Cyberpunk", "Forest", "Royal"];
    const chosen = validThemes.includes(themeName) ? themeName : "Classic";
    document.body.setAttribute("data-theme", chosen);
  }

  // ==========================================
  // VERIFIKASI IDENTITAS & MULAI KUIS
  // ==========================================
  async function autoLookupParticipantName() {
    const npmEl = document.getElementById("inputNpm");
    const tokenEl = document.getElementById("inputToken");
    const hint = document.getElementById("npmLookupHint");
    if (!npmEl || !tokenEl) return;

    const npm = npmEl.value.trim();
    const token = tokenEl.value.trim();
    if (!/^\d{8,15}$/.test(npm)) return;

    try {
      const res = await callGasApi({ action: "cekIdentitasPeserta", token: token, npm: npm }, 1);
      if (res && res.status === "success" && res.nama) {
        document.getElementById("inputNama").value = res.nama;
        if (res.email) state.prefillEmail = res.email;
        if (hint) {
          hint.textContent = "Data mahasiswa ditemukan di database akademik.";
          hint.classList.remove("hidden");
        }
      }
    } catch (e) {}
  }

  async function handleStartKuis(e) {
    e.preventDefault();
    const token = document.getElementById("inputToken").value.trim();
    const npm = document.getElementById("inputNpm").value.trim();
    const nama = document.getElementById("inputNama").value.trim();

    if (!token || !npm || !nama) return;

    ensureAudioContext();
    const btn = document.getElementById("btnMulaiKuis");
    btn.disabled = true;
    btn.innerHTML = '<span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span> Memverifikasi...';

    try {
      const res = await callGasApi({
        action: "mulaiKuis",
        token: token,
        npm: npm,
        nama: nama
      });

      btn.disabled = false;
      btn.innerHTML = '<i class="bi bi-play-fill text-lg"></i> Masuk & Mulai Kuis';

      if (!res || res.status === "error") {
        Swal.fire({
          icon: "error",
          title: "Tidak Dapat Memulai Kuis",
          text: res ? res.message : "Terjadi kesalahan saat memverifikasi token."
        });
        return;
      }

      if (res.status === "waiting") {
        enterWaitingRoom(token, npm, nama, res.judul || "Sesi Kuis Live", res.tema || "Classic");
        return;
      }

      launchQuizArena(token, npm, nama, res, null);
    } catch (err) {
      btn.disabled = false;
      btn.innerHTML = '<i class="bi bi-play-fill text-lg"></i> Masuk & Mulai Kuis';
      Swal.fire({ icon: "error", title: "Koneksi Gagal", text: err.message });
    }
  }

  function enterWaitingRoom(token, npm, nama, judul, tema) {
    applyQuizTheme(tema);
    document.getElementById("waitingQuizTitle").textContent = judul;
    document.getElementById("waitingParticipantName").textContent = `${nama} (${npm})`;
    document.getElementById("screenLogin").classList.add("hidden");
    document.getElementById("screenWaitingRoom").classList.remove("hidden");

    clearInterval(waitingPollInterval);
    waitingPollInterval = setInterval(async () => {
      try {
        const check = await callGasApi({
          action: "mulaiKuis",
          token: token,
          npm: npm,
          nama: nama
        }, 1);

        if (check && check.status === "success") {
          clearInterval(waitingPollInterval);
          document.getElementById("screenWaitingRoom").classList.add("hidden");
          launchQuizArena(token, npm, nama, check, null);
        } else if (check && check.status === "error") {
          clearInterval(waitingPollInterval);
          cancelWaitingRoom();
          Swal.fire({ icon: "error", title: "Sesi Ditutup", text: check.message });
        }
      } catch (e) {}
    }, 5000);
  }

  function cancelWaitingRoom() {
    clearInterval(waitingPollInterval);
    document.getElementById("screenWaitingRoom").classList.add("hidden");
    document.getElementById("screenLogin").classList.remove("hidden");
  }

  function launchQuizArena(token, npm, nama, res, resumeData) {
    state.isActive = true;
    state.isSubmitting = false;
    state.isTransitioning = false;
    state.sessionToken = res.sessionToken || "";
    state.token = token;
    state.npm = npm;
    state.nama = res.verifiedNama || nama;
    if (res.verifiedEmail) state.prefillEmail = res.verifiedEmail;
    state.dataKuis = res.dataKuis || {};
    state.soalList = res.soal || [];
    state.currentIndex = resumeData ? resumeData.currentIndex : 0;
    state.userAnswers = resumeData ? resumeData.userAnswers : [];
    state.cheatCount = Number(res.serverCheatCount || 0);
    state.answeredStreak = resumeData ? resumeData.answeredStreak : 0;
    state.unfocusedSinceMs = 0;
    state.initialViewportArea = window.innerWidth * window.innerHeight;
    state.initialAspectRatio = window.innerWidth / Math.max(1, window.innerHeight);

    applyQuizTheme(state.dataKuis.tema);

    document.getElementById("quizTitleDisplay").textContent = state.dataKuis.judul || "Evaluasi Kuis";
    document.getElementById("participantInfoDisplay").textContent = `${state.nama} (${state.npm})`;
    document.getElementById("totalQuestionNum").textContent = state.soalList.length;
    document.getElementById("timerModeBadge").textContent = `Mode: ${state.dataKuis.timerGlobal || "Per-Soal"}`;
    document.getElementById("cheatCounterLabel").textContent = state.cheatCount;

    const antiBadge = document.getElementById("antiCheatBadge");
    antiBadge.classList.remove("hidden");
    antiBadge.classList.add("flex");

    document.getElementById("screenLogin").classList.add("hidden");
    document.getElementById("screenQuiz").classList.remove("hidden");

    if (state.dataKuis.musikCustom && !audioPrefs.bgmEnabled) {
      toggleBgm();
    }

    if (state.dataKuis.timerGlobal === "Global") {
      const totalDefault = state.soalList.reduce((acc, q) => acc + (parseInt(q.waktu, 10) || 60), 0);
      const serverRemaining = typeof res.sisaDetikServer === "number" ? res.sisaDetikServer : totalDefault;
      if (serverRemaining <= 0) {
        while (state.currentIndex < state.soalList.length) {
          const q = state.soalList[state.currentIndex];
          state.userAnswers.push({ id: q.id, jawaban: "" });
          state.currentIndex++;
        }
        finishQuiz(false);
        return;
      }
      startCountdown(serverRemaining, true);
    }

    renderCurrentQuestion();
  }

  function renderCurrentQuestion() {
    if (state.currentIndex >= state.soalList.length) {
      finishQuiz(false);
      return;
    }

    state.isTransitioning = false;
    const q = state.soalList[state.currentIndex];
    const qNum = state.currentIndex + 1;
    const total = state.soalList.length;

    document.getElementById("currentQuestionNum").textContent = qNum;
    document.getElementById("cardQuestionIndex").textContent = qNum;
    document.getElementById("cardQuestionPoint").textContent = q.poin || 10;
    document.getElementById("quizProgressBar").style.width = `${Math.round(((qNum - 1) / total) * 100)}%`;

    document.getElementById("questionTextContainer").textContent = q.pertanyaan || "";

    const imgWrap = document.getElementById("questionImageWrapper");
    const imgEl = document.getElementById("questionImageEl");
    if (q.gambar && String(q.gambar).trim().startsWith("http")) {
      imgEl.src = String(q.gambar).trim();
      imgWrap.classList.remove("hidden");
    } else {
      imgEl.src = "";
      imgWrap.classList.add("hidden");
    }

    const letters = ["A", "B", "C", "D", "E"];
    const container = document.getElementById("optionsContainer");
    container.innerHTML = "";

    (q.opsi || []).forEach((optText, idx) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "option-card w-full text-left p-3.5 sm:p-4 rounded-xl flex items-center gap-3.5 font-semibold text-sm sm:text-base cursor-pointer";
      btn.dataset.optionValue = optText;
      btn.innerHTML = `
        <span class="w-8 h-8 rounded-lg flex-shrink-0 flex items-center justify-center font-mono-code font-bold text-xs border border-current opacity-85">
          ${letters[idx] || idx + 1}
        </span>
        <span class="flex-1 leading-snug">${escHtml(optText)}</span>
      `;
      btn.addEventListener("click", () => handleSelectOption(btn, optText));
      container.appendChild(btn);
    });

    if (state.dataKuis.timerGlobal !== "Global") {
      const qSeconds = parseInt(q.waktu, 10) || 60;
      startCountdown(qSeconds, false);
    }

    saveMinimalSessionLocal();
  }

  function handleSelectOption(clickedBtn, selectedText) {
    if (!state.isActive || state.isTransitioning || state.isSubmitting) return;
    state.isTransitioning = true;

    if (state.dataKuis.timerGlobal !== "Global") {
      clearInterval(state.timerInterval);
    }

    const q = state.soalList[state.currentIndex];
    state.userAnswers.push({ id: q.id, jawaban: selectedText });
    state.answeredStreak++;

    const allBtns = document.querySelectorAll("#optionsContainer .option-card");
    allBtns.forEach(b => (b.disabled = true));
    clickedBtn.classList.add("option-selected-neutral");
    playSfx("click");

    if (state.answeredStreak >= 2) {
      document.getElementById("streakCountText").textContent = state.answeredStreak;
      document.getElementById("streakBadge").classList.remove("hidden");
      document.getElementById("streakBadge").classList.add("flex");
    }

    state.currentIndex++;
    saveMinimalSessionLocal();

    setTimeout(() => {
      renderCurrentQuestion();
    }, 380);
  }

  function zoomQuestionImage(src) {
    if (!src) return;
    Swal.fire({
      imageUrl: src,
      imageAlt: "Perbesaran Gambar Soal",
      showConfirmButton: false,
      showCloseButton: true,
      width: "auto"
    });
  }

  // ==========================================
  // TIMER MONOTONIC + DETEKSI FOKUS BERKELANJUTAN
  // ==========================================
  function startCountdown(seconds, isGlobal) {
    clearInterval(state.timerInterval);
    state.remainingSeconds = seconds;
    state.targetEndPerfMs = performance.now() + (seconds * 1000);
    renderTimerText();

    state.timerInterval = setInterval(() => {
      if (!state.isActive || state.isSubmitting) {
        clearInterval(state.timerInterval);
        return;
      }

      // Deteksi berkelanjutan jika jendela kehilangan fokus (misal undocked DevTools / overlay)
      if (!document.hasFocus()) {
        if (state.unfocusedSinceMs === 0) {
          state.unfocusedSinceMs = Date.now();
        } else if (Date.now() - state.unfocusedSinceMs > 2500) {
          state.unfocusedSinceMs = Date.now();
          triggerAntiCheatViolation("jendela ujian tidak aktif / membuka jendela lain");
        }
      } else {
        state.unfocusedSinceMs = 0;
      }

      const sisa = Math.ceil((state.targetEndPerfMs - performance.now()) / 1000);
      state.remainingSeconds = Math.max(0, sisa);
      renderTimerText();

      if (state.remainingSeconds <= 0) {
        clearInterval(state.timerInterval);
        if (isGlobal) {
          while (state.currentIndex < state.soalList.length) {
            const q = state.soalList[state.currentIndex];
            state.userAnswers.push({ id: q.id, jawaban: "" });
            state.currentIndex++;
          }
          finishQuiz(false);
        } else if (!state.isTransitioning) {
          state.isTransitioning = true;
          const q = state.soalList[state.currentIndex];
          state.userAnswers.push({ id: q.id, jawaban: "" });
          state.currentIndex++;
          saveMinimalSessionLocal();
          renderCurrentQuestion();
        }
      }
    }, 500);
  }

  function renderTimerText() {
    const sec = Math.max(0, state.remainingSeconds);
    const m = String(Math.floor(sec / 60)).padStart(2, "0");
    const s = String(sec % 60).padStart(2, "0");
    const timerText = document.getElementById("timerText");
    const timerBox = document.getElementById("timerBox");

    timerText.textContent = `${m}:${s}`;
    if (sec <= 10) {
      timerBox.style.borderColor = "#dc2626";
      timerBox.style.color = "#dc2626";
      timerBox.style.backgroundColor = "rgba(220, 38, 38, 0.12)";
    } else {
      timerBox.style.borderColor = "var(--accent-primary)";
      timerBox.style.color = "var(--accent-primary)";
      timerBox.style.backgroundColor = "var(--accent-soft)";
    }
  }

  // ==========================================
  // SISTEM ANTI-CHEAT + STREAMING LOG KE SERVER
  // ==========================================
  function triggerAntiCheatViolation(reason) {
    if (!state.isActive || state.isSubmitting) return;

    const now = Date.now();
    if (now - state.lastCheatTimestamp < 2500) return;
    state.lastCheatTimestamp = now;

    state.cheatCount++;
    document.getElementById("cheatCounterLabel").textContent = state.cheatCount;
    playSfx("warning");

    // Kirim log pelanggaran ke server secara real-time
    callGasApi({
      action: "logCheatEvent",
      token: state.token,
      npm: state.npm,
      sessionToken: state.sessionToken,
      reason: reason
    }, 1).catch(() => {});

    if (state.cheatCount >= 10) {
      Swal.fire({
        icon: "error",
        title: "Batas Pelanggaran Tercapai!",
        text: "Anda telah melanggar aturan integritas sebanyak 10 kali. Ujian otomatis dihentikan dan didiskualifikasi.",
        allowOutsideClick: false,
        confirmButtonText: "Lihat Status"
      }).then(() => {
        finishQuiz(true);
      });
    } else {
      Swal.fire({
        icon: "warning",
        title: `Peringatan Anti-Cheat (${state.cheatCount}/10)`,
        text: `Terdeteksi ${reason}. Tetap berada di layar kuis hingga selesai!`,
        timer: 2800,
        showConfirmButton: true,
        confirmButtonText: "Saya Mengerti"
      });
    }
  }

  // ==========================================
  // SUBMIT AKHIR KE SERVER GAS & RENDER PEMBAHASAN
  // ==========================================
  async function finishQuiz(isDisqualified) {
    if (state.isSubmitting) return;
    state.isSubmitting = true;
    state.isActive = false;
    clearInterval(state.timerInterval);
    stopBgm();

    document.getElementById("quizProgressBar").style.width = "100%";

    Swal.fire({
      title: "Menyimpan Jawaban...",
      text: "Mohon tunggu sebentar, server sedang menghitung dan memverifikasi skor Anda.",
      allowOutsideClick: false,
      didOpen: () => Swal.showLoading()
    });

    try {
      const res = await callGasApi({
        action: "submitKuis",
        token: state.token,
        npm: state.npm,
        nama: state.nama,
        sessionToken: state.sessionToken,
        userAnswers: state.userAnswers,
        cheatCount: state.cheatCount
      }, 3);

      Swal.close();
      clearMinimalSessionLocal();
      playSfx("finish");

      document.getElementById("screenQuiz").classList.add("hidden");
      document.getElementById("antiCheatBadge").classList.add("hidden");
      document.getElementById("screenResult").classList.remove("hidden");

      const skorAkhir = res && res.status === "success" ? res.skor : 0;
      const statusCurang = res && res.curang ? res.curang : (isDisqualified ? "DISKUALIFIKASI" : "Aman");

      document.getElementById("finalScoreDisplay").textContent = skorAkhir;
      document.getElementById("resParticipantName").textContent = state.nama;
      document.getElementById("resParticipantNpm").textContent = state.npm;
      document.getElementById("resQuizTitleLabel").textContent = (state.dataKuis && state.dataKuis.judul) || "Evaluasi Kuis";
      document.getElementById("resTokenLabel").textContent = state.token;
      document.getElementById("resTimestampLabel").textContent = new Date().toLocaleString("id-ID");

      if (state.prefillEmail) {
        document.getElementById("inputResultEmail").value = state.prefillEmail;
      }

      const answeredCount = state.userAnswers.filter(a => a.jawaban && a.jawaban.trim() !== "").length;
      document.getElementById("resAnsweredCount").textContent = `${answeredCount} / ${state.soalList.length}`;

      const integrityEl = document.getElementById("finalIntegrityBadge");
      const iconWrap = document.getElementById("resultIconWrapper");
      const headingEl = document.getElementById("resultHeading");

      if (statusCurang.includes("DISKUALIFIKASI")) {
        headingEl.textContent = "Ujian Didiskualifikasi";
        iconWrap.innerHTML = '<i class="bi bi-x-octagon-fill text-red-600"></i>';
        integrityEl.className = "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold mt-2 bg-red-100 text-red-700";
        integrityEl.innerHTML = `<i class="bi bi-exclamation-triangle-fill"></i> ${escHtml(statusCurang)}`;
      } else if (statusCurang !== "Aman") {
        integrityEl.className = "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold mt-2 bg-amber-100 text-amber-800";
        integrityEl.innerHTML = `<i class="bi bi-shield-exclamation"></i> Status: ${escHtml(statusCurang)}`;
      } else {
        integrityEl.innerHTML = `<i class="bi bi-shield-fill-check"></i> Status: ${escHtml(statusCurang)}`;
      }

      if (res && Array.isArray(res.pembahasan) && res.pembahasan.length > 0) {
        renderAnswerReview(res.pembahasan);
      }

      if (res && res.status !== "success") {
        Swal.fire({ icon: "error", title: "Peringatan Penyimpanan", text: res.message });
      }
    } catch (err) {
      Swal.close();
      state.isSubmitting = false;
      Swal.fire({
        icon: "error",
        title: "Gagal Mengirim Jawaban",
        text: err.message + ". Periksa koneksi internet Anda lalu tekan tombol Kirim Ulang.",
        confirmButtonText: "Kirim Ulang Sekarang"
      }).then(() => {
        finishQuiz(isDisqualified);
      });
    }
  }

  function renderAnswerReview(pembahasanList) {
    const section = document.getElementById("reviewAnswerSection");
    const listEl = document.getElementById("reviewAnswerList");
    listEl.innerHTML = "";

    pembahasanList.forEach((item, idx) => {
      const isCorrect = Boolean(item.benar);
      const card = document.createElement("div");
      card.className = `p-3 rounded-xl border ${isCorrect ? "border-emerald-500/40 bg-emerald-500/10" : "border-red-500/40 bg-red-500/10"}`;
      card.innerHTML = `
        <div class="flex items-start justify-between gap-2 font-bold mb-1">
          <span>${idx + 1}. ${escHtml(item.pertanyaan)}</span>
          <span class="px-2 py-0.5 rounded text-[10px] font-mono-code ${isCorrect ? "bg-emerald-600 text-white" : "bg-red-600 text-white"}">
            ${isCorrect ? `+${item.poin || 0}` : "0"} Poin
          </span>
        </div>
        <div class="theme-muted">Jawaban Anda: <strong class="${isCorrect ? "text-emerald-600" : "text-red-600"}">${escHtml(item.jawabanPeserta || "(Kosong)")}</strong></div>
        ${!isCorrect ? `<div class="text-emerald-600 font-semibold mt-0.5">Kunci Jawaban: ${escHtml(item.kunciJawaban)}</div>` : ""}
      `;
      listEl.appendChild(card);
    });

    section.classList.remove("hidden");
  }

  // ==========================================
  // DOWNLOAD SCREENSHOT PNG (DENGAN NORMALISASI TEMA GELAP)
  // ==========================================
  function downloadResultScreenshot() {
    const target = document.getElementById("resultCaptureArea");
    const btn = document.getElementById("btnDownloadScreenshot");
    if (!target || typeof html2canvas === "undefined") return;

    btn.disabled = true;
    btn.innerHTML = '<span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span> Memproses Gambar...';

    const computed = getComputedStyle(document.body);
    const activeCardBg = computed.getPropertyValue("--card-bg").trim() || "#ffffff";
    const activeTextMain = computed.getPropertyValue("--text-main").trim() || "#0f172a";
    const activeAccentSoft = computed.getPropertyValue("--accent-soft").trim() || "#eff6ff";
    const activeAccentPrimary = computed.getPropertyValue("--accent-primary").trim() || "#2563eb";

    html2canvas(target, {
      scale: 2,
      useCORS: true,
      backgroundColor: activeCardBg,
      onclone: (clonedDoc) => {
        const clonedArea = clonedDoc.getElementById("resultCaptureArea");
        if (clonedArea) {
          clonedArea.style.backgroundColor = activeCardBg;
          clonedArea.style.color = activeTextMain;
        }
        const scoreBox = clonedDoc.getElementById("scoreSummaryBox");
        if (scoreBox) {
          scoreBox.style.backgroundColor = activeAccentSoft;
        }
        const scoreNum = clonedDoc.getElementById("finalScoreDisplay");
        if (scoreNum) {
          scoreNum.style.color = activeAccentPrimary;
        }
      }
    }).then(canvas => {
      const link = document.createElement("a");
      const safeNpm = (state.npm || "Peserta").replace(/[^a-zA-Z0-9]/g, "");
      const safeToken = (state.token || "Kuis").replace(/[^a-zA-Z0-9]/g, "");
      link.download = `Bukti_Kuis_${safeToken}_${safeNpm}.png`;
      link.href = canvas.toDataURL("image/png");
      link.click();

      btn.disabled = false;
      btn.innerHTML = '<i class="bi bi-check-circle-fill"></i> Screenshot Berhasil Diunduh';
      setTimeout(() => {
        btn.innerHTML = '<i class="bi bi-camera-fill"></i> Download Screenshot Bukti Ujian (PNG)';
      }, 2500);
    }).catch(err => {
      btn.disabled = false;
      btn.innerHTML = '<i class="bi bi-camera-fill"></i> Download Screenshot Bukti Ujian (PNG)';
      Swal.fire({ icon: "error", title: "Gagal Membuat Screenshot", text: err.message });
    });
  }

  // ==========================================
  // KIRIM BUKTI HASIL UJIAN KE EMAIL VIA BREVO API
  // ==========================================
  async function sendResultToEmail() {
    const emailInput = document.getElementById("inputResultEmail");
    const btn = document.getElementById("btnSendResultEmail");
    const email = emailInput.value.trim();

    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      Swal.fire({ icon: "warning", title: "Email Tidak Valid", text: "Masukkan alamat email yang benar." });
      return;
    }

    btn.disabled = true;
    btn.innerHTML = '<span class="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span>';

    try {
      const res = await callGasApi({
        action: "kirimEmailHasilKuis",
        email: email,
        token: state.token,
        npm: state.npm,
        nama: state.nama,
        sessionToken: state.sessionToken,
        terjawab: document.getElementById("resAnsweredCount").textContent
      });

      btn.disabled = false;
      btn.innerHTML = '<i class="bi bi-send-fill"></i> Kirim';

      if (res && res.status === "success") {
        emailInput.disabled = true;
        btn.disabled = true;
        btn.innerHTML = '<i class="bi bi-check2"></i> Terkirim';
        Swal.fire({ icon: "success", title: "Email Terkirim", text: res.message });
      } else {
        Swal.fire({ icon: "error", title: "Gagal Mengirim", text: res ? res.message : "Terjadi kesalahan." });
      }
    } catch (err) {
      btn.disabled = false;
      btn.innerHTML = '<i class="bi bi-send-fill"></i> Kirim';
      Swal.fire({ icon: "error", title: "Koneksi Gagal", text: err.message });
    }
  }

  // ==========================================
  // BINDING EVENT LISTENER & PROTEKSI KEYBOARD/DEVTOOLS
  // ==========================================
  window.addEventListener("DOMContentLoaded", () => {
    const params = new URLSearchParams(window.location.search);
    const urlToken = params.get("token");
    if (urlToken) {
      const tokenInput = document.getElementById("inputToken");
      if (tokenInput) tokenInput.value = urlToken.trim();
    }

    document.getElementById("formStartKuis")?.addEventListener("submit", handleStartKuis);
    document.getElementById("inputNpm")?.addEventListener("blur", autoLookupParticipantName);
    document.getElementById("btnCancelWaiting")?.addEventListener("click", cancelWaitingRoom);
    document.getElementById("btnToggleSfx")?.addEventListener("click", toggleSfx);
    document.getElementById("btnToggleBgm")?.addEventListener("click", toggleBgm);
    document.getElementById("btnDownloadScreenshot")?.addEventListener("click", downloadResultScreenshot);
    document.getElementById("btnSendResultEmail")?.addEventListener("click", sendResultToEmail);

    const imgEl = document.getElementById("questionImageEl");
    imgEl?.addEventListener("click", () => zoomQuestionImage(imgEl.src));

    restoreServerSyncedSession(urlToken ? urlToken.trim() : "");
  });

  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      triggerAntiCheatViolation("perpindahan tab browser");
    }
  });

  window.addEventListener("blur", () => {
    triggerAntiCheatViolation("kehilangan fokus jendela ujian");
  });

  window.addEventListener("resize", () => {
    if (!state.isActive || state.isSubmitting) return;
    const currentArea = window.innerWidth * window.innerHeight;
    const currentRatio = window.innerWidth / Math.max(1, window.innerHeight);
    const isRotatedOrientation = (state.initialAspectRatio < 1 && currentRatio > 1) ||
                                 (state.initialAspectRatio > 1 && currentRatio < 1);

    if (isRotatedOrientation && currentArea >= state.initialViewportArea * 0.85) {
      state.initialViewportArea = currentArea;
      state.initialAspectRatio = currentRatio;
      return;
    }

    if (currentArea < state.initialViewportArea * 0.68) {
      triggerAntiCheatViolation("penyusutan area layar / mode split-screen");
    }
  });

  document.addEventListener("contextmenu", e => {
    if (state.isActive && !state.isSubmitting) {
      e.preventDefault();
    }
  });

  window.addEventListener("beforeunload", e => {
    if (state.isActive && !state.isSubmitting) {
      saveMinimalSessionLocal();
      e.preventDefault();
      e.returnValue = "";
    }
  });

  document.addEventListener("keydown", e => {
    if (!state.isActive || state.isSubmitting) return;

    const key = e.key.toUpperCase();
    const isCtrlOrMeta = e.ctrlKey || e.metaKey;

    // Blokir F5 / Ctrl+R / Ctrl+Shift+R
    if (e.key === "F5" || (isCtrlOrMeta && key === "R")) {
      e.preventDefault();
      return;
    }

    // Blokir & catat percobaan DevTools (F12, Ctrl+Shift+I/J/C, Ctrl+U)
    if (
      e.key === "F12" ||
      (isCtrlOrMeta && e.shiftKey && ["I", "J", "C"].includes(key)) ||
      (isCtrlOrMeta && key === "U")
    ) {
      e.preventDefault();
      triggerAntiCheatViolation("percobaan membuka DevTools / Inspeksi Elemen");
      return;
    }

    if (state.isTransitioning) return;
    const mapIdx = { "1": 0, "A": 0, "2": 1, "B": 1, "3": 2, "C": 2, "4": 3, "D": 3 };
    if (mapIdx[key] !== undefined) {
      const btns = document.querySelectorAll("#optionsContainer .option-card");
      if (btns[mapIdx[key]]) {
        btns[mapIdx[key]].click();
      }
    }
  });
})();
